# GitHub API ile review comment gonder
async def post_review_comment(owner, repo, pr_number, review):
    await github.post(
        f'/repos/{owner}/{repo}/pulls/{pr_number}/reviews',
        json={
            'body': review.summary,
            'event': 'COMMENT',
            'comments': [
                {'path': i.file, 'line': i.line, 'body': i.message}
                for i in review.issues
            ]
        }
    )
